package com.mochikibun.monsthub;
import org.junit.Test;
import static org.junit.Assert.*;
import java.time.*;
import org.json.*;
public class HubStateTest {
 private String id(HubState s,int i)throws Exception{return s.accounts().getJSONObject(i).getString("id");}
 @Test public void initialTwelveAndIndependentAccounts()throws Exception {HubState s=TestStates.twelve();assertEquals(12,s.accounts().length());assertEquals(4,s.resetHour());LocalDate d=LocalDate.of(2026,10,18);String task=s.tasks().getJSONObject(0).getString("id");s.check(d,id(s,0),task,true);assertTrue(s.checked(d,id(s,0),task));assertFalse(s.checked(d,id(s,1),task));assertFalse(s.checked(d.plusDays(1),id(s,0),task));}
 @Test public void fourAmJstBoundaryPreservesPreviousRecords()throws Exception{HubState s=TestStates.twelve();Instant before=Instant.parse("2026-10-18T18:59:59Z"),after=Instant.parse("2026-10-18T19:00:00Z");assertEquals(LocalDate.of(2026,10,18),s.day(before));assertEquals(LocalDate.of(2026,10,19),s.day(after));String id=id(s,0);s.check(s.day(before),id,"bond",true);assertTrue(s.checked(s.day(before),id,"bond"));assertFalse(s.checked(s.day(after),id,"bond"));}
 @Test public void manualBondResetDoesNotClearTasksOrYesterday()throws Exception{HubState s=TestStates.twelve();String id=id(s,0),task=s.tasks().getJSONObject(0).getString("id");LocalDate d=LocalDate.of(2026,10,18);s.check(d,id,"bond",true);s.check(d.minusDays(1),id,"bond",true);s.check(d,id,task,true);s.check(d,id,"bond",false);assertFalse(s.checked(d,id,"bond"));assertTrue(s.checked(d.minusDays(1),id,"bond"));assertTrue(s.checked(d,id,task));}
 @Test public void accountRenameKeepsIdAndProgress()throws Exception{HubState s=TestStates.twelve();String id=id(s,0);LocalDate d=LocalDate.of(2026,10,18);s.check(d,id,"bond",true);s.editAccount(id,"先輩","メモ","https://example.com/multi");assertEquals(id,id(s,0));assertTrue(s.checked(d,id,"bond"));assertEquals("先輩",s.account(id).getString("name"));assertEquals(12,s.copy().accounts().length());}
 @Test public void deleteAndAddNeverReuseAccountId()throws Exception{HubState s=TestStates.twelve();String old=id(s,0);s.setOrbs(old,50,"test",Instant.EPOCH);s.check(LocalDate.of(2026,10,18),old,"bond",true);s.deleteAccount(old);assertEquals(11,s.accounts().length());assertEquals(0,s.history().length());String n=s.addAccount("新規");assertNotEquals(old,n);assertFalse(s.checked(LocalDate.of(2026,10,18),n,"bond"));assertEquals(12,s.copy().accounts().length());}
 @Test public void orbBalanceAndHistorySurviveBackup()throws Exception{HubState s=TestStates.twelve();String a=id(s,0),b=id(s,1);s.setOrbs(a,100,"配布",Instant.EPOCH);s.setOrbs(a,50,"ガチャ",Instant.EPOCH.plusSeconds(10));s.setOrbs(b,30,"配布",Instant.EPOCH);HubState copy=HubState.parse(s.json());assertEquals(80,copy.totalOrbs());assertEquals(3,copy.history().length());assertEquals(-50,copy.history().getJSONObject(1).getInt("delta"));assertEquals("ガチャ",copy.history().getJSONObject(1).getString("memo"));}
 @Test public void fullBackupRoundTripIncludesAllData()throws Exception{HubState s=TestStates.twelve();String a=id(s,0);s.editAccount(a,"メイン","日本語メモ","https://example.com/?pass_code=1");String t=s.addTask("イベント");s.check(LocalDate.of(2026,10,18),a,t,true);s.check(LocalDate.of(2026,10,18),a,"bond",true);s.setOrbs(a,123,"理由",Instant.EPOCH);s.setResetHour(6);HubState c=HubState.parse(s.json());assertEquals(6,c.resetHour());assertEquals("日本語メモ",c.account(a).getString("memo"));assertEquals(123,c.totalOrbs());assertTrue(c.checked(LocalDate.of(2026,10,18),a,t));assertTrue(c.checked(LocalDate.of(2026,10,18),a,"bond"));assertEquals("https://example.com/?pass_code=1",c.account(a).getString("url"));}
 @Test public void removedTaskCleansReferences()throws Exception{HubState s=TestStates.twelve();String a=id(s,0),t=s.tasks().getJSONObject(0).getString("id");s.check(LocalDate.of(2026,10,18),a,t,true);s.deleteTask(t);assertEquals(3,s.copy().tasks().length());assertFalse(s.checked(LocalDate.of(2026,10,18),a,t));}
 @Test(expected=Exception.class)public void badBackupSchemaRejected()throws Exception{JSONObject root=new JSONObject(TestStates.twelve().json());root.put("schema_version",99);HubState.parse(root.toString());}
 @Test(expected=Exception.class)public void invalidBooleanBackupRejected()throws Exception{HubState s=TestStates.twelve();LocalDate d=LocalDate.of(2026,10,18);String a=id(s,0);s.check(d,a,"bond",true);JSONObject root=new JSONObject(s.json());root.getJSONObject("days").getJSONObject(d.toString()).getJSONObject(a).put("bond","true");HubState.parse(root.toString());}
 @Test(expected=Exception.class)public void duplicateIdsRejected()throws Exception{JSONObject root=new JSONObject(TestStates.twelve().json());JSONArray a=root.getJSONArray("accounts");a.getJSONObject(1).put("id",a.getJSONObject(0).getString("id"));HubState.parse(root.toString());}
 @Test public void invalidInputDoesNotMutateBalance()throws Exception{HubState s=TestStates.twelve();String a=id(s,0);s.setOrbs(a,10,"",Instant.EPOCH);try{s.setOrbs(a,-1,"",Instant.EPOCH);fail();}catch(IllegalArgumentException expected){}assertEquals(10,s.totalOrbs());assertEquals(1,s.history().length());assertFalse(HubState.validUrl("javascript:alert(1)"));assertFalse(HubState.validUrl("file:///secret"));assertTrue(HubState.validUrl("https://example.com"));}
 @Test public void emptyAccountsBackupIsAllowed()throws Exception{HubState s=TestStates.twelve();while(s.accounts().length()>0)s.deleteAccount(id(s,0));HubState c=s.copy();assertEquals(0,c.accounts().length());assertEquals(0,c.totalOrbs());c.addAccount("再登録");assertEquals(1,c.accounts().length());}
 @Test public void resetHourCanBeCustomized()throws Exception{HubState s=TestStates.twelve();s.setResetHour(0);assertEquals(LocalDate.of(2026,10,19),s.day(Instant.parse("2026-10-18T15:00:00Z")));}
 @Test public void allTasksCompletedCount()throws Exception{HubState s=TestStates.twelve();String a=id(s,0);LocalDate d=LocalDate.of(2026,10,18);for(int i=0;i<s.tasks().length();i++)s.check(d,a,s.tasks().getJSONObject(i).getString("id"),true);assertEquals(1,s.completedAccounts(d));assertEquals(0,s.completedAccounts(d.plusDays(1)));}
}